begin;

-- This follow-up requires the protected booking policy from the first release.
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'bookings'
      and policyname = 'bookings_driver_select' and cmd = 'SELECT' and qual = 'false'
  ) then
    raise exception 'Run 3-Lock-Driver-Booking-Access.sql from the protected offers release first.';
  end if;
end;
$$;

